create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,name text not null,phone text,role text not null default 'instructor' check(role in('admin','instructor')),bank_name text,bank_account text,account_holder text,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,name,phone,role,bank_name,bank_account,account_holder) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'name',new.email),new.raw_user_meta_data->>'phone','instructor',new.raw_user_meta_data->>'bank_name',new.raw_user_meta_data->>'bank_account',new.raw_user_meta_data->>'account_holder') on conflict(id) do nothing;return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
alter table public.profiles enable row level security;create policy profiles_self_admin on public.profiles for select using(id=auth.uid() or public.is_admin());create policy profiles_admin_update on public.profiles for update using(public.is_admin());
create or replace view public.instructor_directory with(security_invoker=false) as select id,name,bank_name,bank_account,account_holder from public.profiles where role='instructor';grant select on public.instructor_directory to anon,authenticated;
create table if not exists public.education_reports(id uuid primary key default gen_random_uuid(),instructor_id uuid not null references public.profiles(id),instructor_name text not null,phone text,course_name text not null,period_start date not null,period_end date not null,total_hours numeric not null,student_count integer not null,ppt_path text,ppt_filename text,created_at timestamptz default now());
alter table public.education_reports enable row level security;create policy reports_own_admin on public.education_reports for all using(instructor_id=auth.uid() or public.is_admin()) with check(instructor_id=auth.uid() or public.is_admin());
create table if not exists public.certificate_requests(id uuid primary key default gen_random_uuid(),student_name text not null,student_dob date not null,student_phone text not null,student_email text,student_address text,course_name text not null,completion_date date not null,request_type text not null check(request_type in('completion','level1','level2')),instructor_id uuid not null references public.profiles(id),payment_date date,status text not null default '접수',created_at timestamptz default now(),constraint payment_required check(request_type='completion' or payment_date is not null));
alter table public.certificate_requests enable row level security;create policy requests_public_insert on public.certificate_requests for insert to anon,authenticated with check(true);create policy requests_instructor_admin_select on public.certificate_requests for select using(instructor_id=auth.uid() or public.is_admin());create policy requests_admin_update on public.certificate_requests for update using(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('education-ppt','education-ppt',false,20971520,array['application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
create policy ppt_upload_own on storage.objects for insert to authenticated with check(bucket_id='education-ppt' and (storage.foldername(name))[1]=auth.uid()::text);create policy ppt_read_own_admin on storage.objects for select to authenticated using(bucket_id='education-ppt' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
